import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Native multi-platform Trend Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-multiplatform-trend-pipeline/spec.md","filePath":"feature/admin-multiplatform-trend-pipeline/spec.md"}'),o={name:"feature/admin-multiplatform-trend-pipeline/spec.md"};function r(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="native-multi-platform-trend-pipeline" tabindex="-1">Native multi-platform Trend Pipeline <a class="header-anchor" href="#native-multi-platform-trend-pipeline" aria-label="Permalink to &quot;Native multi-platform Trend Pipeline&quot;">​</a></h1><h2 id="platform-order-and-start-prerequisites" tabindex="-1">Platform order and start prerequisites <a class="header-anchor" href="#platform-order-and-start-prerequisites" aria-label="Permalink to &quot;Platform order and start prerequisites&quot;">​</a></h2><p>Place Facebook before Threads/TikTok in the platform settings; label it Facebook (pages and groups). Preserve its independent save and avoid nested forms. Explain a disabled manual start with missing Threads session and a clear remedy: configure server session or deselect Threads and save; do not bypass preflight or silently omit a selected platform.</p><h2 id="daily-time-picker" tabindex="-1">Daily time picker <a class="header-anchor" href="#daily-time-picker" aria-label="Permalink to &quot;Daily time picker&quot;">​</a></h2><p>Replace raw cron editing with a daily hour/minute picker, using the server timezone already displayed. Convert HH:mm to the existing five-field cron contract; no API/DB change. Parse zero-padded existing daily values correctly. Preserve non-daily cron unchanged with a read-only summary and explicit action to switch to daily. Empty time blocks saving. Add parallel time/custom/switch/daily validation labels under admin.trendSettings; existing light/dark tokens and keyboard-accessible shared Input/Button.</p><h2 id="objective-user-story" tabindex="-1">Objective / user story <a class="header-anchor" href="#objective-user-story" aria-label="Permalink to &quot;Objective / user story&quot;">​</a></h2><p>Admin controls the existing Facebook, Threads and TikTok native pipeline from <code>?view=trendPipeline</code>. Keep <code>?view=crawl</code> and its legacy settings/API unchanged.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Select at least one platform, enable/pause automatic scheduling, edit a five-field cron using the server timezone displayed by status.</li><li>Keep existing deployment defaults: schedule.json; Facebook source settings; Threads 10 topics, 10 posts/topic, 100 posts total, 600 seconds, 200 comments/post; TikTok manual hashtags plus Creative Center, period 7 days, 1 page/hashtag, top 3 enriched posts, 30 comments/post, media enabled.</li><li>Facebook pages/groups retain their own source editor and revision. Threads sources remain Trending Now topics; TikTok supports manual hashtags plus optional Creative Center. Do not pretend Threads supports page URLs or TikTok pages is a strict post cap.</li><li>Technical input bounds: Threads topics 1–50, posts/topic 1–100, total posts 1–1000, seconds 30–3600, comments 0–500. TikTok period 7/30/120, pages 1–5, enriched top posts 1–30, comments 0–100, at most 100 unique hashtags. A manual hashtag line may include its existing topic label. Require manual hashtags when Creative Center is disabled.</li><li>Persist native configuration with optimistic revision, atomic writes and immutable per-run snapshots. Saved settings apply to the next run; an active run keeps its settings. Saving does not start crawler/scheduler.</li><li>Manual runs may run while the automatic schedule is paused. Preflight checks selected platforms rather than requiring Facebook cookies for TikTok-only runs. Configuration checks are not proof of remote login validity.</li><li>Show selected platforms and per-platform collection progress/counts. Overall completion still requires worker processing, DB publication and resolution. Preserve partial output and report nonzero collector exit truthfully.</li></ul><h2 id="ui-ux-and-states" tabindex="-1">UI/UX and states <a class="header-anchor" href="#ui-ux-and-states" aria-label="Permalink to &quot;UI/UX and states&quot;">​</a></h2><p>Compact schedule/platform configuration, separate platform sections; inline validation, pending/saved/error/stale states and explicit reload on revision conflict. No native browser dialogs. All new UI strings use parallel <code>admin.trendSettings.*</code> keys in vi/en admin.json. Existing source/pipeline keys are reused. Use existing semantic tokens and shared controls; verify light/dark and keyboard/mobile/tablet/desktop.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Admin-only GET/PATCH <code>/api/v1/admin/ai/trend-pipeline/config</code>; internal GET/POST <code>/api/v1/ai/trends/pipeline/config</code>. Body: revision, enabled, cron, platforms, threads limits, tiktok options/hashtags. Reject unknown fields, invalid values and stale updates with structured 400/409; storage failures 503. Never expose sessions, API keys or local paths.</p><h2 id="edge-cases-definition-of-done" tabindex="-1">Edge cases / definition of done <a class="header-anchor" href="#edge-cases-definition-of-done" aria-label="Permalink to &quot;Edge cases / definition of done&quot;">​</a></h2><p>No enabled platform, invalid cron, duplicate hashtags, corrupt persisted settings, simultaneous saves, interruption and recovery remain safe. Legacy settings are independent. Code, docs, isolated verification and Web CI pass.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No credential editor, new providers, downstream trend algorithm/DB schema changes, live crawling, production config updates, automatic scheduler startup or legacy-page consolidation.</p>',17)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
